#!/usr/bin/env node
'use strict';

// Bundles the CommonJS core (lib/) into one browser script: web/js/core.bundle.js
// The Node modules "fs", "path" and "crypto" are replaced by the shims in lib/shims.
// Runs automatically before "tauri dev" / "tauri build" (see src-tauri/tauri.conf.json).
//
// Usage in the browser: const { SNESROM } = window.ASRU.require('core/snesrom');

const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const LIB = path.join(ROOT, 'lib');
const OUT = path.join(ROOT, 'web', 'js', 'core.bundle.js');
const SHIMS = { fs: 'shims/fs.js', path: 'shims/path.js', crypto: 'shims/crypto.js' };
const SKIP = new Set(['cli']); // command line runs with Node.js only

function collect(dir, list = []) {
  for (const name of fs.readdirSync(dir).sort()) {
    const full = path.join(dir, name);
    const rel = path.relative(LIB, full).split(path.sep).join('/');
    if (fs.statSync(full).isDirectory()) {
      if (!SKIP.has(rel)) collect(full, list);
    } else if (name.endsWith('.js')) {
      list.push(rel);
    }
  }
  return list;
}

const modules = collect(LIB);
let out = '// Generated by scripts/bundle-core.js - do not edit\n';
out += '(function () {\n  \'use strict\';\n  const defs = {};\n';

for (const rel of modules) {
  const code = fs.readFileSync(path.join(LIB, rel), 'utf8');
  out += `\n  defs[${JSON.stringify(rel)}] = function (module, exports, require) {\n${code}\n  };\n`;
}

out += `
  const SHIMS = ${JSON.stringify(SHIMS)};
  const cache = {};

  function normalize(parts) {
    const out = [];
    for (const p of parts) {
      if (p === '' || p === '.') continue;
      if (p === '..') out.pop();
      else out.push(p);
    }
    return out.join('/');
  }

  function resolve(from, name) {
    if (SHIMS[name]) return SHIMS[name];
    if (!name.startsWith('.')) throw new Error('Unknown module: ' + name);
    const dir = from.split('/').slice(0, -1);
    const base = normalize(dir.concat(name.split('/')));
    for (const candidate of [base, base + '.js', base + '/index.js']) {
      if (defs[candidate]) return candidate;
    }
    throw new Error('Cannot find module ' + name + ' from ' + from);
  }

  function load(id) {
    if (cache[id]) return cache[id].exports;
    const module = { exports: {} };
    cache[id] = module;
    defs[id].call(module.exports, module, module.exports, (name) => load(resolve(id, name)));
    return module.exports;
  }

  window.ASRU = {
    require: (name) => load(resolve('', name.startsWith('.') ? name : './' + name)),
  };
})();
`;

fs.mkdirSync(path.dirname(OUT), { recursive: true });
fs.writeFileSync(OUT, out);
console.log(`core bundle: ${modules.length} modules -> ${path.relative(ROOT, OUT)} (${Math.round(out.length / 1024)} kByte)`);
